tool_input.new_string:
// 禅道6363：审核中变更挂变更维度 busId 时，busCode 须成对切到变更码 qybgxq，
// 否则以 040100 + changeId 查询会落空（快照附件存储在 qybgxq 维度）。
displayAppendixAtChangeDimension() {
  return !this.isEntryNetworkPage && isCompanyRecordChangeUnderAdminReview({
    activeChangeId: this.activeChangeId,
    activeChangeDisplayStatus: this.activeChangeDisplayStatus,
    bizState: this.form.bizState,
    isChanging: this.form.isChanging
  })
},
displayAppendixBusCode() {
  if (this.isEntryNetworkPage) return ENTRY_NETWORK_APPENDIX_BUS_CODE
  if (this.displayAppendixAtChangeDimension) return DEVELOPER_CHANGE_APPENDIX_BUS_CODE
  return this.licenseBusCode
},

